<?php
require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$q=$pdo->prepare('SELECT h.*,pd.name previous_department,pp.name previous_position,nd.name new_department,np.name new_position FROM employment_histories h LEFT JOIN departments pd ON pd.id=h.previous_department_id LEFT JOIN positions pp ON pp.id=h.previous_position_id LEFT JOIN departments nd ON nd.id=h.department_id LEFT JOIN positions np ON np.id=h.position_id WHERE h.employee_id=? ORDER BY h.effective_date DESC,h.id DESC');$q->execute([$employee['id']]);$history=$q->fetchAll();$pageTitle='My employment';require __DIR__.'/../includes/header.php';?><div class="mb-7"><p class="text-sm text-slate-500">Current employment information and permitted history</p><h1 class="font-display text-3xl font-bold mt-1">My employment</h1></div><section class="bg-white border rounded-xl p-6"><div class="grid md:grid-cols-3 gap-5 text-sm"><?php foreach(['Department'=>'department_name','Position'=>'position_name','Branch'=>'branch_name','Employment type'=>'employment_type','Status'=>'employment_status','Date hired'=>'date_hired'] as $label=>$field):?><div><p class="text-xs text-slate-400"><?=e($label)?></p><p class="font-semibold mt-1"><?=e($employee[$field]??'—')?></p></div><?php endforeach;?></div></section><section class="bg-white border rounded-xl p-6 mt-6"><h2 class="font-display text-xl font-bold">Employment history</h2><div class="overflow-x-auto mt-4"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400"><tr><th class="py-3">Effective</th><th>Event</th><th>Department</th><th>Position</th><th>Status</th></tr></thead><tbody class="divide-y"><?php foreach($history as $item):?><tr><td class="py-3"><?=e($item['effective_date'])?></td><td><?=e($item['event_type'])?></td><td><?=e(($item['previous_department']??'—').' → '.($item['new_department']??'—'))?></td><td><?=e(($item['previous_position']??'—').' → '.($item['new_position']??'—'))?></td><td><?=e(($item['previous_status']??'—').' → '.($item['new_status']??'—'))?></td></tr><?php endforeach;?></tbody></table><?php if(!$history):?><p class="text-sm text-slate-500 mt-4">No employment history available.</p><?php endif;?></div></section><?php require __DIR__.'/../includes/footer.php';